typedef struct { int elem[100]; int length; } SqList;
int LocateElem(const SqList *L, int e) {
    for (int j = 0; j < L->length; ++j)
        if (L->elem[j] == e) return j + 1;
    return 0;
}

typedef struct { int elem[100]; int length; } SqList;
int ListInsert(SqList *L, int i, int e) {
    if (!L || i < 1 || i > L->length + 1) return 0;
    if (L->length == 100) return 0;
    for (int j = L->length - 1; j >= i - 1; --j)
        L->elem[j + 1] = L->elem[j];
    L->elem[i - 1] = e;
    ++L->length;
    return 1;
}
int ListDelete(SqList *L, int i, int *out) {
    if (!L || !out || i < 1 || i > L->length) return 0;
    *out = L->elem[i - 1];
    for (int j = i; j < L->length; ++j)
        L->elem[j - 1] = L->elem[j];
    --L->length;
    return 1;
}

#include <stdlib.h>
typedef struct LNode { int data; struct LNode *next; } LNode, *LinkList;
int PushFront(LinkList L, int e) {
    if (!L) return 0;
    LNode *p = malloc(sizeof *p);
    if (!p) return 0;
    p->data = e;
    p->next = L->next;
    L->next = p;
    return 1;
}

#include <stdlib.h>
typedef struct LNode { int data; struct LNode *next; } LNode, *LinkList;
/* out指向已初始化为NULL的变量；成功才发布结果。 */
int BuildTail(LinkList *out, const int a[], int n) {
    if (!out || *out != NULL || n < 0 || (n > 0 && !a)) return 0;
    LinkList L = malloc(sizeof *L);
    if (!L) return 0;
    L->next = NULL;
    LNode *r = L;
    for (int i = 0; i < n; ++i) {
        LNode *p = malloc(sizeof *p);
        if (!p) {
            while (L) {
                LNode *q = L->next;
                free(L);
                L = q;
            }
            return 0;
        }
        p->data = a[i];
        p->next = NULL;
        r->next = p;
        r = p;
    }
    *out = L;
    return 1;
}

