typedef struct LNode { int data; struct LNode *next; } LNode, *LinkList;
int DeleteFirst(LinkList L, int x, int *out) {
    if (!L || !out) return 0;
    LNode *p = L;
    while (p->next && p->next->data != x) p = p->next;
    LNode *q = p->next;
    if (!q) return 0;
    *out = q->data;
    p->next = q->next;
    free(q);
    return 1;
}
